ALTER TABLE room_categories ADD COLUMN room_type TEXT;
ALTER TABLE room_categories ADD COLUMN nightly_rate_paise INTEGER CHECK(nightly_rate_paise IS NULL OR nightly_rate_paise > 0);
ALTER TABLE room_categories ADD COLUMN max_adults_approved INTEGER CHECK(max_adults_approved IS NULL OR max_adults_approved > 0);
ALTER TABLE room_categories ADD COLUMN max_children_approved INTEGER CHECK(max_children_approved IS NULL OR max_children_approved >= 0);
ALTER TABLE room_categories ADD COLUMN max_occupancy INTEGER CHECK(max_occupancy IS NULL OR max_occupancy > 0);
ALTER TABLE room_categories ADD COLUMN currency TEXT NOT NULL DEFAULT 'INR' CHECK(currency = 'INR');
ALTER TABLE room_categories ADD COLUMN tax_percent REAL CHECK(tax_percent IS NULL OR (tax_percent >= 0 AND tax_percent <= 100));
ALTER TABLE room_categories ADD COLUMN details_status TEXT NOT NULL DEFAULT 'pending' CHECK(details_status IN ('pending','approved','rejected'));
ALTER TABLE room_categories ADD COLUMN inventory_status TEXT NOT NULL DEFAULT 'pending' CHECK(inventory_status IN ('pending','approved','rejected'));
ALTER TABLE room_categories ADD COLUMN occupancy_status TEXT NOT NULL DEFAULT 'pending' CHECK(occupancy_status IN ('pending','approved','rejected'));
ALTER TABLE room_categories ADD COLUMN rates_status TEXT NOT NULL DEFAULT 'pending' CHECK(rates_status IN ('pending','approved','rejected'));
ALTER TABLE room_categories ADD COLUMN tax_status TEXT NOT NULL DEFAULT 'pending' CHECK(tax_status IN ('pending','approved','rejected'));
ALTER TABLE room_categories ADD COLUMN photos_status TEXT NOT NULL DEFAULT 'pending' CHECK(photos_status IN ('pending','approved','rejected'));
ALTER TABLE room_categories ADD COLUMN publication_status TEXT NOT NULL DEFAULT 'unpublished' CHECK(publication_status IN ('unpublished','published'));
ALTER TABLE room_categories ADD COLUMN created_at TEXT NOT NULL DEFAULT '';
ALTER TABLE room_categories ADD COLUMN updated_at TEXT NOT NULL DEFAULT '';
UPDATE room_categories SET created_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP;
ALTER TABLE pricing_rules ADD COLUMN approved INTEGER NOT NULL DEFAULT 0 CHECK(approved IN (0,1));
CREATE INDEX IF NOT EXISTS ix_room_categories_publication ON room_categories(active,publication_status,details_status,inventory_status,occupancy_status,rates_status);
